    Definition cs_ok : ltac2:(zQ "40!jp4!hq9!h8!jpa>2cs@1$2@2$0@2$0$1$3$1P") := ltac2:(zQ "h10!jp4!hq9!jpa!jpf!hs5!jq5!js1!jsb!jt2!n9!h8!nf!n4!kh8!km0!kmf!kp1\2cs@1$a@2$0@2$0$1$2$1@2$3@3$c$9@3$h0@2$0@2$0$1$2$1$d^1$b@2$3@3$6@2$0@2$0$1$2$1\1c@2$0@2$0$1$2$1@2$5@1$e^1@1$f^1^1@3$6@2$0@2$0$1$2$1\1c@2$0@2$0$1$2$1M0\1c@2$0@2$0$1$2$1P^1\1p@2$0$1$2\1z$1M0\1p@2$0$1$2P^2\1a$1\1w$2@2$3@2$4+vhgg0^2@2$3@2$4@2$7^2@1$8^1+hitgg0@2$5@2$4@2$7^2@1$8^1+hgrmh4@2$4+hgrmh8^2^1").

    Record tstat (cs : list (Z * nat * Z)) (mem : word -> option byte) : Prop := TS {
      ts_inv   : mem_inv rsegs mem;
      ts_stk   : stk rsegs mem slo spm;
      ts_top   : stk rsegs mem spm (bv_unsigned sp0 - 48);
      ts_cells : cells_ok mem cs;
      ts_tid   : exists t, rdn RSEGS mem (Z_to_bv 64 0x10b610) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 t)) /\ 0 < t < 2 ^ 22;
