    (* [comment removed for export] *)
    Lemma exit_tailM : forall regs mem model s LB p (A n : Z) (status : word) cs (P : (word -> option byte) -> Prop) pending,
      cs_ok cs ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x10b6b8 -> getr regs 8 = status ->
      getr regs 9 = Z_to_bv 64 A ->
      HeapMF_iface.hs_RHEAP HM s LB mem -> In (p, A, n) LB -> HeapMF_iface.hs_KREL HM s model -> m_fs model = fs0 ->
      fd_lookup (m_fds model) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
      tstatM cs mem -> P mem ->
      (forall m m', P m -> frame_mod m m' (regL_w sp0) -> P m') ->
      (forall m m' LB, P m -> rheap_pres LB spm m m' -> P m') ->
      (forall mem' model' regs', tstatM cs mem' -> P mem' -> (exists s' LB', HeapMF_iface.hs_RHEAP HM s' LB' mem') ->
          m_halted model' = None -> m_vm_lazy model' = [] ->
          fd_lookup (m_fds model') (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
          getr regs' 2 = Z_to_bv 64 (bv_unsigned sp0 - 48) -> getr regs' 4 = Z_to_bv 64 0x10b6b8 -> getr regs' 10 = status ->
          exit_preH regs' mem' model' status pending) ->
      realizes RSEGS (mkCfg (mkst regs (Z_to_bv 64 0x475c4) mem (seg_rom RSEGS)) model)
               (t_emit (W 1 pending) (t_exit (bv_and status (Z_to_bv 64 255)) fs0)).
Proof.
